import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveOutputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CpioArchiveOutputStream#close()
 */
public class CpioArchiveOutputStream_close_TriageGen2Test {

    /**
     * Mock OutputStream to track if close was called.
     */
    private static class MockOutputStream extends ByteArrayOutputStream {
        boolean closed = false;

        @Override
        public void close() throws IOException {
            this.closed = true;
            super.close();
        }
    }



    /**
     * Tests that calling close() multiple times does nothing after the first call.
     * This covers the branch: if (!this.closed)
     */
    @Test
    public void testClose_WhenAlreadyClosed_DoesNothing() throws IOException {
        MockOutputStream mockOut = new MockOutputStream();
        CpioArchiveOutputStream cpioOut = new CpioArchiveOutputStream(mockOut, (short) 0);

        // First close
        cpioOut.close();
        Assert.assertTrue("First close should close mock", mockOut.closed);

        // Second close
        cpioOut.close();
        Assert.assertTrue("Second close should not throw exception", true);
        Assert.assertTrue("Mock should still be closed", mockOut.closed);
    }


}

package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FilterOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveOutputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CpioArchiveOutputStream#close()
 */
public class CpioArchiveOutputStream_close_TriageGen2Test {

    /**
     * Mock OutputStream to track if close was called.
     */
    private static class MockOutputStream extends ByteArrayOutputStream {
        boolean closed = false;

        @Override
        public void close() throws IOException {
            this.closed = true;
            super.close();
        }
    }





    /**
     * Tests that an IOException in the underlying stream's close method is propagated.
     */
    @Test(expected = IOException.class)
    public void testClose_WhenUnderlyingStreamThrowsException_ThrowsIOException() throws IOException {
        OutputStream errorOut = new OutputStream() {
            @Override
            public void write(int b) throws IOException {
                throw new IOException("Simulated failure");
            }
            @Override
            public void close() throws IOException {
                throw new IOException("Simulated close failure");
            }
        };

        CpioArchiveOutputStream cpioOut = new CpioArchiveOutputStream(errorOut, (short) 0);
        cpioOut.close();
    }
}
